import re

_UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'week': 604800, 'weeks': 604800,
}

_ISO_RE = re.compile(
    r'^P'
    r'(?:(?P<weeks>\d+(?:\.\d+)?)W)?'
    r'(?:(?P<days>\d+(?:\.\d+)?)D)?'
    r'(?:T'
    r'(?:(?P<hours>\d+(?:\.\d+)?)H)?'
    r'(?:(?P<minutes>\d+(?:\.\d+)?)M)?'
    r'(?:(?P<seconds>\d+(?:\.\d+)?)S)?'
    r')?$',
    re.IGNORECASE,
)

_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)')


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("duration must be a string")

    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # bare non-negative integer
    if re.fullmatch(r'\d+', s):
        return int(s)

    # ISO 8601 duration
    if s[:1].upper() == 'P':
        return _parse_iso8601(s)

    # clock notation: hh:mm:ss or mm:ss
    if re.fullmatch(r'\d+(?:\.\d+)?(?::\d+(?:\.\d+)?){1,2}', s):
        return _parse_clock(s)

    # number+unit components
    return _parse_components(s)


def _parse_iso8601(s: str) -> int:
    match = _ISO_RE.fullmatch(s)
    if not match:
        raise ValueError(f"invalid ISO 8601 duration: {s!r}")

    groups = match.groupdict()
    if all(v is None for v in groups.values()):
        raise ValueError(f"invalid ISO 8601 duration: {s!r}")

    total = 0.0
    unit_seconds = {
        'weeks': 604800,
        'days': 86400,
        'hours': 3600,
        'minutes': 60,
        'seconds': 1,
    }
    for key, value in groups.items():
        if value is not None:
            total += float(value) * unit_seconds[key]

    return round(total)


def _parse_clock(s: str) -> int:
    parts = s.split(':')
    if len(parts) == 3:
        h, m, sec = parts
        total = float(h) * 3600 + float(m) * 60 + float(sec)
    elif len(parts) == 2:
        m, sec = parts
        total = float(m) * 60 + float(sec)
    else:
        raise ValueError(f"invalid clock duration: {s!r}")

    if total < 0:
        raise ValueError(f"negative duration: {s!r}")

    return round(total)


def _parse_components(s: str) -> int:
    pos = 0
    total = 0.0
    matched_any = False

    for match in _COMPONENT_RE.finditer(s):
        gap = s[pos:match.start()]
        if gap.strip() != '':
            raise ValueError(f"invalid duration: {s!r}")

        number, unit = match.groups()
        unit_key = unit.lower()
        if unit_key not in _UNIT_SECONDS:
            raise ValueError(f"unknown unit: {unit!r}")

        total += float(number) * _UNIT_SECONDS[unit_key]
        matched_any = True
        pos = match.end()

    trailing = s[pos:]
    if trailing.strip() != '':
        raise ValueError(f"invalid duration: {s!r}")

    if not matched_any:
        raise ValueError(f"invalid duration: {s!r}")

    if total < 0:
        raise ValueError(f"negative duration: {s!r}")

    return round(total)

